import json, sys

raw = json.load(sys.stdin)
inner = json.loads(raw['result'])
exps = inner['data']['experiments']

# Target conditions and models
conditions = ['exception_only', 'ae_only', 'vota', 'loop_only', 'no_trace']
models = {
    'qwen7b': 'Qwen-7B',
    'deepseek': 'DeepSeek-6.7B', 
    'codellama13b': 'CodeLlama-13B',
    'qwen15b': 'Qwen-1.5B'
}

# Candidate experiment keys for each condition x model
# Qwen-7B is the default (no prefix) or has qwen7b_ prefix
# Others have their prefix

targets = {}
for cond in conditions:
    for model_prefix, model_name in models.items():
        key = (cond, model_name)
        candidates = []
        for exp_name, exp_data in exps.items():
            if exp_data.get('status') != 'DONE':
                continue
            # Check if this experiment matches condition and model
            name = exp_name.lower()

            # For Qwen-7B: either no model prefix or explicit qwen7b_
            # For others: must have explicit prefix

            if model_prefix == 'qwen7b':
                # Match: vota_seed42 (no prefix, default=qwen7b), or qwen7b_vota_seed42
                # But NOT deepseek_vota, codellama13b_vota, qwen15b_vota
                other_prefixes = ['deepseek_', 'codellama13b_', 'qwen15b_']
                has_other_prefix = any(name.startswith(p) for p in other_prefixes)

                if has_other_prefix:
                    continue

                # Check condition match
                if cond == 'vota':
                    if 'vota' in name and 'no_ae' not in name and 'exception' not in name and 'loop' not in name and 'ae_only' not in name:
                        # Exclude vota_ae_only, vota_exception_only, vota_loop_only, vota_no_ae
                        if name.startswith('vota_seed') or name.startswith('qwen7b_vota'):
                            candidates.append((exp_name, exp_data))
                elif cond == 'exception_only':
                    if ('exception_only' in name) and ('nomarker' not in name) and ('dynamics' not in name):
                        if name.startswith('exception_only_seed') or name.startswith('qwen7b_exception_only'):
                            candidates.append((exp_name, exp_data))
                elif cond == 'ae_only':
                    if name.startswith('ae_only_seed') or (name.startswith('vota_ae_only') and model_prefix == 'qwen7b'):
                        candidates.append((exp_name, exp_data))
                elif cond == 'loop_only':
                    if name.startswith('loop_only_seed') or name.startswith('vota_loop_only'):
                        candidates.append((exp_name, exp_data))
                elif cond == 'no_trace':
                    if name.startswith('no_trace_seed') or name.startswith('qwen7b_no_trace'):
                        candidates.append((exp_name, exp_data))
            else:
                # Other models: must start with model_prefix_
                if not name.startswith(model_prefix + '_'):
                    continue
                rest = name[len(model_prefix) + 1:]
                if cond == 'vota':
                    if rest.startswith('vota_seed'):
                        candidates.append((exp_name, exp_data))
                elif cond == 'exception_only':
                    if rest.startswith('exception_only_seed') and 'nomarker' not in rest:
                        candidates.append((exp_name, exp_data))
                elif cond == 'ae_only':
                    if rest.startswith('ae_only_seed'):
                        candidates.append((exp_name, exp_data))
                elif cond == 'loop_only':
                    if rest.startswith('loop_only_seed'):
                        candidates.append((exp_name, exp_data))
                elif cond == 'no_trace':
                    if rest.startswith('no_trace_seed'):
                        candidates.append((exp_name, exp_data))

        targets[key] = candidates

# Print all candidates with full details
for (cond, model_name), cands in sorted(targets.items()):
    print(f'=== {model_name} / {cond} ({len(cands)} candidates) ===')
    for exp_name, exp_data in cands:
        m = exp_data.get('metrics', {})
        s = exp_data.get('spec', {})
        print(f'  {exp_name}:')
        print(f'    model_name: {s.get(\"model_name\", \"N/A\")}')
        print(f'    seed: {s.get(\"seed\", \"N/A\")}')
        print(f'    accuracy: {m.get(\"accuracy\", \"N/A\")}')
        print(f'    ci_95: {m.get(\"ci_95\", \"N/A\")}')
        print(f'    n_samples: {m.get(\"n_samples\", \"N/A\")}')
        print(f'    eval_data: {s.get(\"eval_data\", \"N/A\")}')
        print(f'    conclusion: {exp_data.get(\"conclusion\", \"N/A\")}')
    print()
"

